-- Seed: 2026-27 Tuesday Dinner. Generated by scripts/make_seed_sql.py from data/2026-27/tuesday-dinner/.
-- Safe to re-run: never overwrites winners or draw shots entered through the site.
begin;

on conflict (season, shift, team_no) do update set
  name = excluded.name, first_half_end_week = excluded.first_half_end_week;

on conflict (season, shift, week, home_no, away_no) do update set
  game_date = excluded.game_date, draw_time = excluded.draw_time, sheet = excluded.sheet;

commit;

-- Check: expect 13 teams and 120 games for this shift.
select (select count(*) from public.teams where season = '2026-27' and shift = 'Tuesday Dinner') as teams,
       (select count(*) from public.games where season = '2026-27' and shift = 'Tuesday Dinner') as games;
